def _rounded(numerator, denominator, mode):
    if mode == "half_up":
        return (2 * numerator + denominator) // (2 * denominator)
    return numerator // denominator


def _build_component_06():
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = _rounded(raw * (10000 - discount), 10000, mode)
            tax = _rounded(net * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        candidates = [job for job in jobs if job["id"] not in blocked]
        best_ids = None
        best_value = None

        for subset in __import__("itertools").combinations(candidates, k):
            ids = [job["id"] for job in subset]
            id_set = set(ids)
            if not mandatory.issubset(id_set):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["start"] < ordered[i - 1]["end"]
                   for i in range(1, len(ordered))):
                continue
            value = sum(job["value"] for job in subset)
            selected = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and selected < best_ids)):
                best_value, best_ids = value, selected

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        required_bit = {node: 1 << i for i, node in enumerate(required)}
        full_mask = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = required_bit.get(source, 0)
        start_state = (source, initial_mask, 0)
        start_time = data["start"]
        distances = {start_state: start_time}
        queue = [(start_time, source, initial_mask, 0)]
        coupons = data["coupons"]
        deadline = data["deadline"]

        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full_mask and used == coupons:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < coupons:
                    options.append((max(2, edge["duration"] - edge.get("discount", 0)), used + 1))
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > deadline:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | required_bit.get(next_node, 0)
                    next_state = (next_node, next_mask, next_used)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_component_01(),
    "component_02": _build_component_02(),
    "component_03": _build_component_03(),
    "component_04": _build_component_04(),
    "component_05": _build_component_05(),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
